async function seedPeriode(classe: string, periode: number, semaines: SemaineRaw[]) {
  for (let i = 0; i < semaines.length; i++) {
    const s = semaines[i];
    const semaineNum = s.n || (i + 1);
    const entry = MOIS_MAP.find(e => e.p === periode && e.s === semaineNum);
    if (!entry) {
      console.warn(`  WARN: pas de mapping mois pour P${periode}S${semaineNum}`);
      continue;
    }
    if (DRY_RUN) {
      console.log(`  [dry] ${entry.mois} S${entry.n} — ${s.theme}`);
      continue;
    }
    const row = await prisma.repartitionSemaine.upsert({
      where: { classe_mois_semaine: { classe, mois: entry.mois, semaine: entry.n } },
      create: { classe, mois: entry.mois, semaine: entry.n, dateDebut: entry.date, theme: s.theme, sousTheme: s.sousTheme },
      update: { dateDebut: entry.date, theme: s.theme, sousTheme: s.sousTheme },
    });
    await prisma.repartitionMatiere.deleteMany({ where: { semaineId: row.id } });
    await prisma.repartitionMatiere.createMany({
      data: s.matieres.map(md => ({
        semaineId: row.id,
        matiere: md.matiere,
        topic: md.topic,
        approche: md.approche,
        transmission: JSON.stringify(md.transmission),
        exercices: JSON.stringify(md.exercices),
      })),
    });
    console.log(`  ✓ ${classe} ${entry.mois} S${entry.n} — ${s.theme} (${s.matieres.length} matières)`);
  }
}

async function main() {
  console.log('=== Seed répartition 10ème ===');
  if (!FORCE && !DRY_RUN) {
    console.log('Passe --force pour écrire en base, ou --dry-run pour simuler.');
    process.exit(1);
  }

  if (FORCE) {
    // Supprimer les anciennes classes 11ème et 12ème
    const ancien = await prisma.repartitionSemaine.findMany({
      where: { classe: { in: ['11eme', '12eme'] } },
      select: { id: true },
    });
    if (ancien.length > 0) {
      await prisma.repartitionMatiere.deleteMany({ where: { semaineId: { in: ancien.map(r => r.id) } } });
      await prisma.repartitionSemaine.deleteMany({ where: { id: { in: ancien.map(r => r.id) } } });
      console.log(`Supprimé ${ancien.length} semaines 11ème/12ème`);
    }
  }

  await seedPeriode('10eme', 1, P1);
  await seedPeriode('10eme', 2, P2);
  await seedPeriode('10eme', 3, P3);
  await seedPeriode('10eme', 4, P4);
  await seedPeriode('10eme', 5, P5);

  console.log('=== Seed répartition 9ème ===');
  await seedPeriode('9eme', 1, P1_9);
  await seedPeriode('9eme', 2, P2_9);
  await seedPeriode('9eme', 3, P3_9);
  await seedPeriode('9eme', 4, P4_9);
  await seedPeriode('9eme', 5, P5_9);

  console.log('=== Seed répartition 8ème — Septembre ===');
  await seedPeriode('8eme', 1, P1_8);

  console.log('=== Seed répartition 7ème — Septembre ===');
  await seedPeriode('7eme', 1, P1_7);

  console.log('=== Seed répartition 11ème (CP) — Septembre ===');
  await seedPeriode('11eme', 1, P1_11);

  console.log('=== Seed répartition 12ème (Maternelle) — Septembre ===');
  await seedPeriode('12eme', 1, P1_12);

  console.log('Done.');
}

main()
  .catch(e => { console.error(e); process.exit(1); })
  .finally(() => prisma.$disconnect());
